#!/usr/bin/env python3
"""New A51 freeze plus L12-51 expansion; existing requests stay immutable."""
import sys
sys.dont_write_bytecode=True
import pathlib,importlib.util,json,math,collections
P=pathlib.Path(__file__).resolve().parent
s=importlib.util.spec_from_file_location('q',P/'step-03-wave5f-common.py');q=importlib.util.module_from_spec(s);s.loader.exec_module(q)
s=importlib.util.spec_from_file_location('pkt',P/'step-03-wave3-packet.py');pkt=importlib.util.module_from_spec(s);s.loader.exec_module(pkt)
m=q.m;PIN=q.PIN;NEW=tuple(f'{i:03}' for i in range(105,114))
method=(P/'step-03-wave5e-review-request.md').read_text().split('## Python per-field extractor',1)[1].split('## Per-set A51 selection',1)[0]

def request(name,title,index,preface):
 lines=['# '+title,'',f'Fixed author pin `{PIN}`. Read A51, L12-21..L12-51, the latest authoring rules digest in progress.md and the record schema in step-03-authoring-request.md. Patch RECORDS only; no consumer edit or authority flip. **Reviewers never run checker/probes.** Started/accepted 0/0.','',preface,'',f'Frozen index `{name.replace("request.md","index.json")}`: **{index["selectedFiles"]} whole files / {index["selectedEdges"]} edges / {len(index["parts"])} parts**. Source, diff and record hashes bind every file. Review every assigned edge, full diff and complete pinned source/targets, including preserve, parks, row flips, status prose, author-added edges/exclusions and witnesses.','', '## Python per-field extractor'+method]
 if 'perSet' in index:
  lines+=['## Per-set A51 selection','','| Set | Patched / seeded | Mandatory | Patched+mandatory | Unpatched eligible / seeded | Distinct |','|---|---:|---:|---:|---:|---:|']
  for x in index['perSet']:lines.append(f"| {x['set']} | {x['patchedPopulation']}/{x['patchedSeedSample']} | {x['mandatoryFiles']} | {x['patchedAndMandatoryDistinct']} | {x['unpatchedEligiblePopulation']}/{x['unpatchedSample']} | {x['distinctSelected']} |")
  lines+=['','Both strata use their own exact NUL seed, sha256(seed + NUL + path) rank and ceil(15%) per set. Mandatory ≥65,536 source bytes OR ≥40 inventory edges; the reused selector additionally includes files with ≥40 total edges, a stronger union. Reviewed denominators 0, rework pending. >3% in either stratum expands to EVERY file of its own set, including zero-edge/park/preserve/row-flip records. Never pool, replace or reseed.']
 lines+=['','## Assigned parts','']
 for part in index['parts']:
  lines += [f"### Part {part['part']:02} → `{pathlib.Path(part['report']).name}`",'',f"{part['fileCount']} whole files / {part['edges']} edges / {part['sourcePlusRecordBytes']} source-plus-record bytes."+(' **Indivisible file, own part: read ≤100-edge pages and bounded fields.**' if part['indivisibleOversize'] else ''),'','| Set | Consumer | Inclusion | Edges |','|---|---|---|---:|']
  for row in part['files']:lines.append(f"| {row['set']} | `{row['file']}` | {', '.join(row['strata'])} | {row['edges']} |")
  lines.append('')
 lines+=['## Handback','','Write only your uniquely assigned report. Give a whole-file verdict with every edge read and exact record/diff hashes, evidence and dissent. Report reviewed-file denominator/rework numerator per set AND stratum, distinguishing overlaps. Separate semantic defects, record-text fixes and Lead questions. No repairs, checker/probes, dispatch or acceptance. Lead owns independent review, preview, actual runner-commit accounting and later drift revalidation. GAP-01/02/03, workflow/RUL10 carry and Step 5 parity remain separate gates; this packet claims no set closure or Phase 9 authorization. Names follow the explicit brief namespace; no fgOS CLI in this author Unit.']
 (P/name).write_text('\n'.join(lines)+'\n')

def main():
 sets=tuple(p.stem.removeprefix('batch-') for p in sorted((P/'step-03-records').glob('batch-[0-9][0-9][0-9].jsonl')));rs=[r for b in sets for r in q.load(b)];by={r['file']:r for r in rs};wave=[r for r in rs if r['reviewSet'] in {'batch-'+b for b in NEW}];assert {r['reviewSet'] for r in wave}=={'batch-'+b for b in NEW}
 binding={'pin':PIN,'rule':'All canonical current records; historical manifest bindings are retained unchanged','recordFiles':[{'path':str(m.REL/'step-03-records'/f'batch-{b}.jsonl'),'sha256':m.sha((P/'step-03-records'/f'batch-{b}.jsonl').read_bytes())} for b in sets],'files':[pkt.row(r,[]) for r in rs]};q.save('step-03-wave5f-binding-manifest.json',binding)
 m.SETS=NEW;freeze=m.manifest_view(wave,PIN);freeze['unpatchedStrata']={}
 for b in NEW:
  selected=next(x['selected'] for x in freeze['sets'] if x['set']=='batch-'+b);pop=sorted(r['file'] for r in wave if r['reviewSet']=='batch-'+b and not r['diff'] and r['edges'] and r['file'] not in selected);seed='A51-step03-file-v1-unpatched\0'+PIN+'\0batch-'+b;ranks=sorted([{'file':f,'rankHash':m.sha(seed+'\0'+f)} for f in pop],key=lambda x:(x['rankHash'],x['file']))
  freeze['unpatchedStrata'][b]={'seed':seed,'population':pop,'populationCount':len(pop),'ranks':ranks,'selected':[x['file'] for x in ranks[:math.ceil(.15*len(pop))]],'reviewedDenominator':0,'reworkNumerator':'pending'}
 freeze['recordFiles']=[{'path':str(m.REL/'step-03-records'/f'batch-{b}.jsonl'),'sha256':m.sha((P/'step-03-records'/f'batch-{b}.jsonl').read_bytes())} for b in NEW];q.save('step-03-wave5f-manifest.json',freeze)
 rows=[];accounts=[]
 for g in freeze['sets']:
  b=g['set'];u=freeze['unpatchedStrata'][b.removeprefix('batch-')];wanted=sorted(set(g['selected']+u['selected']));accounts.append({'set':b,'allFiles':sum(r['reviewSet']==b for r in wave),'patchedPopulation':g['populationCount'],'patchedSeedSample':len(g['sample']),'mandatoryFiles':len(g['mandatoryWitnesses']),'patchedAndMandatoryDistinct':len(g['selected']),'unpatchedEligiblePopulation':u['populationCount'],'unpatchedSample':len(u['selected']),'distinctSelected':len(wanted),'patchedStratum':{'selectedDenominator':len(g['selected']),'reviewedDenominator':0,'reworkNumerator':'pending'},'unpatchedStratum':{'selectedDenominator':len(u['selected']),'reviewedDenominator':0,'reworkNumerator':'pending'}})
  for f in wanted:
   strata=[]
   if f in g['sample']:strata.append('patched-seeded')
   if f in [x['file'] for x in g['mandatoryWitnesses']]:strata.append('mandatory-threshold')
   if f in u['selected']:strata.append('unpatched-seeded')
   rows.append(pkt.row(by[f],strata))
 index={'pin':PIN,'manifest':'step-03-wave5f-manifest.json','binding':'step-03-wave5f-binding-manifest.json','selectedFiles':len(rows),'selectedEdges':sum(x['edges'] for x in rows),'parts':pkt.parts(rows,'review-a38-step-03-wave5f-p'),'perSet':accounts,'reviewersStarted':0,'accepted':0,'scope':'New batches 105–113 only'}
 q.save('step-03-wave5f-review-index.json',index)
 request('step-03-wave5f-review-request.md','Step 3 wave 5f — independent A51 review',index,'New batches **105–113 only**. Review source/evidence columns and actual carriage independently from live Related; whole migration rows/status semantics; ratchet default/root parity; retained laws versus missing full projection carry; self-Related removal; current process/runner pointers; exact target claims in proposals. Candidate status or a date does not make live prose history. All parks name their own blocker and require their full source/target search evidence to be judged independently.')
 delta=json.loads((P/'step-03-wave5f-ruling-changes.json').read_text());changed={x['file'] for x in delta['changes']};prior=json.loads((P/'step-03-wave5c-review-index.json').read_text());reviewed={x['file'] for part in prior['parts'] if (P/pathlib.Path(part['report']).name).exists() for x in part['files']};expanded={r['file'] for r in rs if r['reviewSet'] in ('batch-126','batch-130')};remaining=expanded-reviewed;wanted=remaining|changed
 erows=[pkt.row(by[f],(['L12-51-every-remaining-batch126-or130-file'] if f in remaining else [])+(['L12-51-changed-file-targeted-re-review'] if f in changed else [])) for f in sorted(wanted,key=lambda f:(by[f]['reviewSet'],f))]
 exp={'pin':PIN,'rule':'L12-51 / A51','binding':'step-03-wave5f-binding-manifest.json','historicalReviewIndex':'step-03-wave5c-review-index.json','previouslyReviewedIn126And130':sorted(expanded&reviewed),'remaining126And130':sorted(remaining),'targetedChangedFiles':sorted(changed),'selectedFiles':len(erows),'selectedEdges':sum(x['edges'] for x in erows),'parts':pkt.parts(erows,'review-a38-step-03-wave5c-x-p'),'reviewersStarted':0,'accepted':0,'reviewedDenominator':0,'reworkNumerator':'pending','coverageBySet':[{'set':b,'files':sum(x['set']==b for x in erows),'reviewedDenominator':0,'reworkNumerator':'pending'} for b in sorted({x['set'] for x in erows})]};q.save('step-03-wave5c-expansion-review-index.json',exp)
 request('step-03-wave5c-expansion-review-request.md','Step 3 wave 5c — remaining-file expansion and L12-51 targeted re-review',exp,'L12-51 expands batch-126 and batch-130 to every not-yet-reviewed file, including zero-edge records, plus targeted re-review of EVERY file changed by this rework pass (record-text changes included). Previous reviewed files/reports and frozen memberships remain historical, never replaced. Re-check D7 anchor 04994; new launcher line-63 deleted 0031 edge; present-tense 04982 RUL34/RUL37; 01325 approval-gate verbs; all 332 sourceCaptureIds capture/provenance keys and their actual doctor reader parity; 04114 dead link; corrected switchboard exact file owners and pathless status prose under coverage.switchboardStatusRowFlips; 0004 English/Vietnamese successor correspondence, retained-root suffixes, removed 0000 index projection note and resolved 04966 elision. Include the 06547 paired root-label/relative-destination patch. All assigned files are indivisible; larger files have their own part and ≤100-edge readingPages.')
 q.save('step-03-wave5f-population.json',{'pin':PIN,'completedBatches':list(NEW),'stopBoundary':'113; no partial next batch, no authorship of ≥114','files':len(wave),'inventoryEdges':sum(len(r['inventoryEdgeIds']) for r in wave),'addedEdges':sum(len(r['edges'])-len(r['inventoryEdgeIds']) for r in wave),'edges':sum(len(r['edges']) for r in wave),'patchedFiles':sum(bool(r['diff']) for r in wave),'dispositions':dict(collections.Counter(e['disposition'] for r in wave for e in r['edges'])),'parks':dict(collections.Counter(e['blockedCategory'] for r in wave for e in r['edges'] if e['disposition']=='parked')),'openLeadRulingEdgesPerSet':{b:[e['edgeId'] for r in wave if r['reviewSet']=='batch-'+b for e in r['edges'] if e.get('blockedCategory')=='lead-ruling'] for b in NEW},'newReview':{'files':len(rows),'edges':index['selectedEdges'],'parts':len(index['parts'])},'expansionReview':{'files':len(erows),'edges':exp['selectedEdges'],'parts':len(exp['parts'])}})
 print(json.dumps({'newFiles':len(wave),'sampleFiles':len(rows),'sampleParts':len(index['parts']),'expansionFiles':len(erows),'expansionParts':len(exp['parts'])}))
if __name__=='__main__':main()
